begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values ('f0000000-0000-4000-8000-000000003141','pos-import@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000003141","role":"authenticated"}';
select set_config('test.tenant',create_tenant('POS import test','pos-import-test',gen_random_uuid())::text,true);
select set_config('test.seller',register_seller(current_setting('test.tenant')::uuid,gen_random_uuid(),'Synthetic seller','pos-import@example.test','')::text,true);
select publish_store_policy(current_setting('test.tenant')::uuid,gen_random_uuid(),null,
 (current_store_policy(current_setting('test.tenant')::uuid)->'policy') || '{"vatModeConsignmentPrivate":"consignment_margin","vatModeStoreOwned":"store_full"}'::jsonb);
select store_shopify_connection(current_setting('test.tenant')::uuid,'synthetic.myshopify.com','Synthetic','SEK','{"iv":"test","tag":"test","data":"test"}','read_products',null);
select set_config('test.context',inventory_import_context(current_setting('test.tenant')::uuid,array[current_setting('test.seller')::uuid]),true);
select set_config('test.product','{"productId":"gid://shopify/Product/1","variantId":"gid://shopify/ProductVariant/1","title":"Synthetic jacket","sku":"OLD-1","barcode":"0123456789012","priceOre":12525,"currency":"SEK","quantity":1,"active":true}',true);
select set_config('test.request',gen_random_uuid()::text,true);
select throws_ok($$select commit_pos_import(current_setting('test.tenant')::uuid,current_setting('test.request')::uuid,'shopify','wrong.myshopify.com',current_setting('test.product')::jsonb,'create',null,current_setting('test.seller')::uuid,current_setting('test.context'),true)$$,'P0001','POS_CONNECTION_CHANGED','source account pinned');
select throws_ok($$select commit_pos_import(current_setting('test.tenant')::uuid,current_setting('test.request')::uuid,'shopify','synthetic.myshopify.com',current_setting('test.product')::jsonb,'create',null,current_setting('test.seller')::uuid,current_setting('test.context'),false)$$,'P0001','CUSTODY_REQUIRED','custody explicit');
select throws_ok($$select commit_pos_import(current_setting('test.tenant')::uuid,current_setting('test.request')::uuid,'shopify','synthetic.myshopify.com',current_setting('test.product')::jsonb,'create',null,current_setting('test.seller')::uuid,'stale',true)$$,'P0001','IMPORT_CHANGED','changed terms stop import');
select throws_ok($$select commit_pos_import(current_setting('test.tenant')::uuid,current_setting('test.request')::uuid,'shopify','synthetic.myshopify.com',jsonb_set(current_setting('test.product')::jsonb,'{quantity}','2'),'create',null,current_setting('test.seller')::uuid,current_setting('test.context'),true)$$,'P0001','POS_ITEM_UNSUPPORTED','multi-unit variant cannot represent a unique item');
select set_config('test.result',commit_pos_import(current_setting('test.tenant')::uuid,current_setting('test.request')::uuid,'shopify','synthetic.myshopify.com',current_setting('test.product')::jsonb,'create',null,current_setting('test.seller')::uuid,current_setting('test.context'),true)::text,true);
select set_config('test.item',current_setting('test.result')::jsonb->'item'->>'id',true);
select is((select count(*) from items where tenant_id=current_setting('test.tenant')::uuid),1::bigint,'new item created');
select is((select snapshot->>'barcode' from pos_product_links where tenant_id=current_setting('test.tenant')::uuid),'0123456789012','barcode preserved including leading zero');
select is((select price_ore from item_prices where tenant_id=current_setting('test.tenant')::uuid),12525::bigint,'exact price');
select is(commit_pos_import(current_setting('test.tenant')::uuid,current_setting('test.request')::uuid,'shopify','synthetic.myshopify.com',current_setting('test.product')::jsonb,'create',null,current_setting('test.seller')::uuid,current_setting('test.context'),true),current_setting('test.result')::jsonb,'same request replay');
select is(commit_pos_import(current_setting('test.tenant')::uuid,gen_random_uuid(),'shopify','synthetic.myshopify.com',current_setting('test.product')::jsonb,'link',current_setting('test.item')::uuid,null,null,false)->>'created','false','existing link reused');
select throws_ok($$select commit_pos_import(current_setting('test.tenant')::uuid,gen_random_uuid(),'shopify','synthetic.myshopify.com',jsonb_set(current_setting('test.product')::jsonb,'{variantId}','"gid://shopify/ProductVariant/2"'),'link',current_setting('test.item')::uuid,null,null,false)$$,'P0001','POS_ALREADY_LINKED','one item cannot map to two source variants');
select throws_ok($$select prepare_shopify_product(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid)$$,'P0001','POS_SOURCE_MANAGED','outbound export cannot duplicate or overwrite source');
select is((pos_import_preview(current_setting('test.tenant')::uuid,'shopify','synthetic.myshopify.com',jsonb_build_array(current_setting('test.product')::jsonb))->0->'linked'->>'id'),current_setting('test.item'),'preview shows already linked');
select is((select count(*) from pos_product_links where tenant_id=current_setting('test.tenant')::uuid),1::bigint,'no duplicate mapping');
select throws_ok($$update pos_product_links set account='other'$$,'42501','permission denied for table pos_product_links','no direct writes');
select throws_ok($$select commit_pos_import(gen_random_uuid(),gen_random_uuid(),'shopify','synthetic.myshopify.com',current_setting('test.product')::jsonb,'link',current_setting('test.item')::uuid,null,null,false)$$,'42501','FORBIDDEN','cross-tenant refused');
select is(item_sync_status(current_setting('test.tenant')::uuid,array[current_setting('test.item')::uuid])->0->'connections'->0->>'status','linked','shared item status distinguishes a link from an export');
select is(item_sync_status(current_setting('test.tenant')::uuid,array[current_setting('test.item')::uuid])->0->'connections'->0->>'canExport','false','source-managed item cannot be auto-exported');
select set_config('test.purchase',register_purchase(current_setting('test.tenant')::uuid,gen_random_uuid(),'Synthetic purchase',5000,'Synthetic receipt',true)::text,true);
select set_config('test.own',gen_random_uuid()::text,true);
select accept_item(current_setting('test.tenant')::uuid,current_setting('test.own')::uuid,'purchase',current_setting('test.purchase')::uuid,null,12525);
select is(commit_pos_import(current_setting('test.tenant')::uuid,gen_random_uuid(),'shopify','synthetic.myshopify.com',jsonb_set(current_setting('test.product')::jsonb,'{variantId}','"gid://shopify/ProductVariant/2"'),'link',current_setting('test.own')::uuid,null,null,false)->'item'->>'ownership','store','existing own item can be linked without new purchase');
select is((select count(*) from items where tenant_id=current_setting('test.tenant')::uuid),2::bigint,'linking creates no inventory');
create function pg_temp.pos_order(g text,at timestamptz) returns jsonb language sql as $$
 select jsonb_build_object('orderGid','gid://shopify/Order/'||g,'name','#'||g,'occurredAt',at,'updatedAt',at,'currency','SEK','amountOre',12525,'financialStatus','PAID','test',false,'cancelled',false,
 'lines',jsonb_build_array(jsonb_build_object('lineNo',1,'sku','OLD-1','variantGid','gid://shopify/ProductVariant/1','description','Synthetic jacket','quantity',1,'priceOre',12525)));
$$;
select set_config('test.cursor',shopify_order_cursor(current_setting('test.tenant')::uuid),true);
select record_shopify_order_page(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.cursor'),'2026-10-14T00:00:00Z',jsonb_build_array(pg_temp.pos_order('31401',now()-interval '1 hour')));
select is((select hold_reason from shopify_orders where tenant_id=current_setting('test.tenant')::uuid and name='#31401'),'missing_item','historical sales never applied to new intake');
select set_config('test.order',pg_temp.pos_order('31402',clock_timestamp()+interval '1 second')::text,true);
select record_shopify_order_page(current_setting('test.tenant')::uuid,gen_random_uuid(),'2026-10-14T00:00:00Z','2026-10-14T00:00:01Z',jsonb_build_array(current_setting('test.order')::jsonb));
select is((select count(*) from sales where tenant_id=current_setting('test.tenant')::uuid and provider='shopify'),1::bigint,'future sale matches the external variant despite old SKU');
select is((select item_id from sale_lines where tenant_id=current_setting('test.tenant')::uuid),current_setting('test.item')::uuid,'correct consignment sold');
select record_shopify_order_page(current_setting('test.tenant')::uuid,gen_random_uuid(),'2026-10-14T00:00:01Z','2026-10-14T00:00:02Z',jsonb_build_array(current_setting('test.order')::jsonb || jsonb_build_object('refunds',jsonb_build_array(jsonb_build_object('refundGid','gid://shopify/Refund/31402','occurredAt',clock_timestamp()+interval '2 seconds','amountOre',12525,'lines',jsonb_build_array(jsonb_build_object('lineNo',1,'sku','OLD-1','variantGid','gid://shopify/ProductVariant/1','quantity',1,'amountOre',12525)))))));
select is((select count(*) from sale_returns where tenant_id=current_setting('test.tenant')::uuid),1::bigint,'refund matches original sale by variant');
select is((select count(*) from seller_ledger_entries where tenant_id=current_setting('test.tenant')::uuid and kind='credit_reversal'),1::bigint,'ordinary return rule reverses seller credit');
select is(commit_pos_import(current_setting('test.tenant')::uuid,current_setting('test.request')::uuid,'shopify','synthetic.myshopify.com',current_setting('test.product')::jsonb,'create',null,current_setting('test.seller')::uuid,current_setting('test.context'),true),current_setting('test.result')::jsonb,'lost import response survives later sale and return');
reset role;
set local role authenticated;
select set_config('test.merchant',gen_random_uuid()::text,true);
select store_paypal_oauth(current_setting('test.tenant')::uuid,current_setting('test.merchant')::uuid,'{"iv":"aWl2","tag":"dGFn","data":"ZGF0YQ=="}',now()+interval '1 hour',0);
select set_config('test.paypal',jsonb_build_object('productId',gen_random_uuid(),'variantId',gen_random_uuid(),'title','Synthetic PayPal coat','sku','OLD-COAT','barcode','0099988877766','priceOre',12525,'currency','SEK','quantity',null,'active',true)::text,true);
select set_config('test.paypalItem',(commit_pos_import(current_setting('test.tenant')::uuid,gen_random_uuid(),'paypal',current_setting('test.merchant'),current_setting('test.paypal')::jsonb,'create',null,current_setting('test.seller')::uuid,current_setting('test.context'),true)->'item'->>'id'),true);
select throws_ok($$select prepare_zettle_product(current_setting('test.tenant')::uuid,current_setting('test.paypalItem')::uuid)$$,'P0001','POS_SOURCE_MANAGED','PayPal source item cannot be exported over original');
select set_config('test.paypalLine',jsonb_build_object('lineNo',1,'reference',null,'labelConflict',false,'description','Synthetic coat','priceOre',12525,'productUuid',current_setting('test.paypal')::jsonb->>'productId','variantUuid',current_setting('test.paypal')::jsonb->>'variantId')::text,true);
select set_config('test.paypalSale',gen_random_uuid()::text,true);
select set_config('test.paypalFacts',jsonb_build_object('externalId',current_setting('test.paypalSale'),'occurredAt',clock_timestamp()+interval '1 second','currency','SEK','amountOre',12525,'blockedReason',null,'lines',jsonb_build_array(current_setting('test.paypalLine')::jsonb))::text,true);
select record_zettle_page(current_setting('test.tenant')::uuid,gen_random_uuid(),null,'one',jsonb_build_array(current_setting('test.paypalFacts')::jsonb||jsonb_build_object('externalId',gen_random_uuid(),'occurredAt',now()-interval '1 hour')));
select is((select count(*) from sales where tenant_id=current_setting('test.tenant')::uuid and provider='zettle'),0::bigint,'historical PayPal sale cannot consume imported stock');
select record_zettle_page(current_setting('test.tenant')::uuid,gen_random_uuid(),'one','two',jsonb_build_array(current_setting('test.paypalFacts')::jsonb));
select is((select count(*) from sales where tenant_id=current_setting('test.tenant')::uuid and provider='zettle'),1::bigint,'future PayPal sale matches linked product and variant');
select record_zettle_page(current_setting('test.tenant')::uuid,gen_random_uuid(),'two','three',jsonb_build_array(current_setting('test.paypalFacts')::jsonb||jsonb_build_object('externalId',gen_random_uuid(),'refundOf',current_setting('test.paypalSale'),'occurredAt',clock_timestamp()+interval '2 seconds','amountOre',-12525,'blockedReason','refund')));
select is((select count(*) from sale_returns where tenant_id=current_setting('test.tenant')::uuid and item_id=current_setting('test.paypalItem')::uuid),1::bigint,'PayPal refund matches original sale without a catalog export');
select is((select count(*) from zettle_stock_intents where tenant_id=current_setting('test.tenant')::uuid),0::bigint,'import and return never initialize or change source stock');
select is((select count(*) from zettle_catalog_candidates(current_setting('test.tenant')::uuid) where item_id=current_setting('test.paypalItem')::uuid),0::bigint,'source items excluded before automatic export pagination');
select is(items_search_page(current_setting('test.tenant')::uuid,'{"syncProvider":"paypal","syncStatus":"linked"}','title','asc',25,0)->>'total','1','shared item search filters linked PayPal items');
select is(items_search_page(current_setting('test.tenant')::uuid,'{"syncProvider":"shopify","syncStatus":"linked"}','title','asc',25,0)->>'total','2','shared item search pairs provider and linked status');
reset role;
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values(gen_random_uuid(),'f0000000-0000-4000-8000-000000003141','totp','verified',now(),now());
set local role authenticated;
select throws_like($$select pos_import_search(current_setting('test.tenant')::uuid,'jacket')$$,'%AUTH_REQUIRED%','MFA required');
set local role anon;
select throws_ok($$select pos_import_search(current_setting('test.tenant')::uuid,'jacket')$$,'42501','permission denied for function pos_import_search','anonymous denied');
reset role;
select * from finish();
rollback;
